import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { canonicalSha256 } from '../../core/canonical-json.mjs';
const ROOT=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'../../..');
const DEFAULT=path.join(ROOT,'capabilities-v2/graph.json');
const sha=/^[a-f0-9]{64}$/;
function unique(records,key,name){const seen=new Set();for(const record of records){if(!record||typeof record[key]!=='string')throw new TypeError(`${name} record is missing ${key}`);if(seen.has(record[key]))throw new Error(`Duplicate ${name} ${record[key]}`);seen.add(record[key]);}return seen;}
export function compileCapabilityGraphV2(input){const graph=structuredClone(input);if(graph.schemaVersion!==2)throw new TypeError('Capability Graph schemaVersion must be 2');for(const key of ['outcomes','techniques','providers','evaluators','relations'])if(!Array.isArray(graph[key]))throw new TypeError(`${key} must be an array`);const outcomes=unique(graph.outcomes,'outcomeId','outcome');const techniques=unique(graph.techniques,'techniqueId','technique');const providers=unique(graph.providers,'providerId','provider');const evaluators=unique(graph.evaluators,'evaluatorId','evaluator');for(const item of [...graph.outcomes,...graph.techniques])if(!sha.test(item.contractSha256??''))throw new TypeError(`Invalid contract hash for ${item.outcomeId??item.techniqueId}`);const satisfies=new Set();const validates=new Set();for(const edge of graph.relations){if(!['satisfies','deliveredBy','validatedBy','requires','optionalRequires','specializes','composedWith','conflictsWith','alternativeTo','supersedes','invalidates'].includes(edge.type))throw new Error(`Unsupported graph relation: ${edge.type}`);if(edge.type==='satisfies'){if(!techniques.has(edge.from)||!outcomes.has(edge.to))throw new Error(`Dangling satisfies relation ${edge.from} -> ${edge.to}`);if(!edge.mappingEvidence||!Number.isFinite(edge.fitScore)||edge.fitScore<0||edge.fitScore>100)throw new Error(`Mapping evidence and fitScore are required for ${edge.from}`);satisfies.add(edge.from);}if(edge.type==='deliveredBy'){if(!techniques.has(edge.from)||!providers.has(edge.to))throw new Error(`Dangling provider relation ${edge.from} -> ${edge.to}`);}if(edge.type==='validatedBy'){if(!techniques.has(edge.from)||!evaluators.has(edge.to))throw new Error(`Dangling evaluator relation ${edge.from} -> ${edge.to}`);validates.add(edge.from);}}
 for(const technique of graph.techniques){if(!satisfies.has(technique.techniqueId))throw new Error(`Technique has no outcome mapping evidence: ${technique.techniqueId}`);if(!validates.has(technique.techniqueId))throw new Error(`Technique has no evaluator binding: ${technique.techniqueId}`);}const payload={schemaVersion:2,outcomes:graph.outcomes.sort((a,b)=>a.outcomeId.localeCompare(b.outcomeId)),techniques:graph.techniques.sort((a,b)=>a.techniqueId.localeCompare(b.techniqueId)),providers:graph.providers.sort((a,b)=>a.providerId.localeCompare(b.providerId)),evaluators:graph.evaluators.sort((a,b)=>a.evaluatorId.localeCompare(b.evaluatorId)),relations:graph.relations.sort((a,b)=>`${a.type}:${a.from}:${a.to}`.localeCompare(`${b.type}:${b.from}:${b.to}`))};return Object.freeze({...payload,graphSha256:canonicalSha256(payload)});}
export async function loadCapabilityGraphV2(file=DEFAULT){return compileCapabilityGraphV2(JSON.parse(await readFile(file,'utf8')));}
export function techniquesForOutcome(graph,outcomeId){return graph.relations.filter((edge)=>edge.type==='satisfies'&&edge.to===outcomeId).map((edge)=>edge.from);}
export function outcomesForTechnique(graph,techniqueId){return graph.relations.filter((edge)=>edge.type==='satisfies'&&edge.from===techniqueId).map((edge)=>edge.to);}
export function providersForTechnique(graph,techniqueId){return graph.relations.filter((edge)=>edge.type==='deliveredBy'&&edge.from===techniqueId).map((edge)=>edge.to);}
export function evaluatorsForTechnique(graph,techniqueId){return graph.relations.filter((edge)=>edge.type==='validatedBy'&&edge.from===techniqueId).map((edge)=>edge.to);}
